<?php
require_once __DIR__.'/db.php';require_once __DIR__.'/includes/functions.php';require_role(['student']);
$st=$pdo->prepare("SELECT id FROM students WHERE user_id=?");$st->execute([current_user_id()]);$student=$st->fetch();
if(!$student)exit('Профили донишҷӯ ёфт нашуд.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$d=(int)$_POST['dormitory_id'];$check=$pdo->prepare("SELECT COUNT(*) FROM applications WHERE student_id=? AND status='pending'");$check->execute([$student['id']]);if((int)$check->fetchColumn()===0){$ins=$pdo->prepare("INSERT INTO applications(student_id,dormitory_id,status) VALUES(?,?,'pending')");$ins->execute([$student['id'],$d]);flash('Дархост фиристода шуд.');}else flash('Шумо аллакай дархости интизорӣ доред.','error');redirect('my_applications.php');}
$dorms=$pdo->query("SELECT id,name FROM dormitories")->fetchAll();$st=$pdo->prepare("SELECT a.*,d.name dormitory_name FROM applications a JOIN dormitories d ON d.id=a.dormitory_id WHERE a.student_id=? ORDER BY a.id DESC");$st->execute([$student['id']]);$rows=$st->fetchAll();$pageTitle='Дархостҳои ман';require __DIR__.'/includes/header.php';?>
<h1>Дархостҳои ман</h1><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Интихоби хобгоҳ</label><select name="dormitory_id" required><?php foreach($dorms as $d):?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><button>Фиристодани дархост</button></form></div><div class="table-wrap"><table><tr><th>ID</th><th>Хобгоҳ</th><th>Сана</th><th>Вазъият</th></tr><?php foreach($rows as $r):?><tr><td><?=$r['id']?></td><td><?=e($r['dormitory_name'])?></td><td><?=e($r['submitted_at'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php require __DIR__.'/includes/footer.php';?>
